function isValidEmail(email) {
  // Verifica que el email tenga al menos un carácter antes del @
  if (!email || email.length === 0) {
    return false;
  }

  // Verifica que haya exactamente un carácter @
  if (!email.includes('@')) {
    return false;
  }

  // Extrae la parte después del @
  const localPart = email.split('@')[1];

  // Verifica que el local part no esté vacío
  if (!localPart) {
    return false;
  }

  // Verifica que el local part contenga al menos un punto
  if (!localPart.includes('.')) {
    return false;
  }

  // Verifica que el local part no comience con un punto
  if (localPart.startsWith('.')) {
    return false;
  }

  // Verifica que el local part no termine con un punto
  if (localPart.endsWith('.')) {
    return false;
  }

  // Verifica que el local part no comience con un número
  if (localPart.startsWith('0')) {
    return false;
  }

  // Verifica que el local part no termine con un número
  if (localPart.endsWith('0')) {
    return false;
  }

  // Si todos los checks pasan, es un email válido
  return true;
}

